/* Chalkle data. Game list + icons imported from Chud's games.js.
   Regenerate with: node tools/import-chud.mjs <path-to-chud-games.js>
   Add player counts with playing: N per entry when you have live data. */

/* Flash games run through Ruffle. Ruffle itself is self-hosted at
   /assets/ruffle/ (ruffle.min.js + its companion .wasm files), so the whole
   flash pipeline - player and SWF - stays on this site's own origin. No
   CDN link involved, so nothing to block. Mirrors the wrapper used by the
   UGS library, minus the remote Ruffle. */
/* Resolve a site-relative path to an absolute URL at generation time, so the
   Ruffle wrapper keeps working even inside an opaque (blob:null) about:blank
   tab that has no base URL of its own. Falls back to the current origin when
   the generated runtime-config isn't present (local testing). */
function absUrl(path) {
  var base =
    (typeof window !== "undefined" && window.SCHOOL_CENTER_CONFIG && SCHOOL_CENTER_CONFIG.mainUrl) ||
    (typeof location !== "undefined" ? location.origin : "");
  base = String(base || "").replace(/\/+$/, "");
  return base + path;
}

/* Ruffle SWF loader. The wrapper opens inside a blob / about:blank tab whose
   origin is opaque (blob:null/...), so a relative SWF path can't be resolved
   by Ruffle's URL constructor. Fix: fetch the SWF bytes in the wrapper and
   hand them straight to Ruffle as raw data, so no URL resolution happens at
   all. swf is a relative or absolute path to the .swf on this same server. */
function ruffleHtml(swf) {
  var path = String(swf);
  if (path.indexOf("://") === -1 && path.charAt(0) !== "/") path = "/" + path;
  /* The about:blank / blob popup inherits the site's origin, so resolve both
     the SWF and the self-hosted Ruffle runtime against location.origin at
     runtime. The script is injected via DOM (never document.write - a literal
     </script> inside a JS string would terminate the script block when the
     page is re-parsed inside the blob). Ruffle loads from this same site, so
     nothing touches a CDN and there is nothing to block. */
  var runFn =
    "function run(){" +
    "var path=" + JSON.stringify(path) + ";" +
    "var abs=String(path).indexOf('://')!==-1 ? path : location.origin + (path.charAt(0)==='/'?'':'/') + path;" +
    "var r=window.RufflePlayer&&(window.RufflePlayer.newest?window.RufflePlayer.newest():window.RufflePlayer);" +
    "if(!r)return;var p=r.createPlayer();p.config={allowScriptAccess:true};" +
    "p.style.width='100vw';p.style.height='100vh';document.body.appendChild(p);" +
    "p.load({url:abs});" +
    "}";
  var loader =
    "(function(){" +
    "function boot(){var r=window.RufflePlayer&&(window.RufflePlayer.newest?window.RufflePlayer.newest():window.RufflePlayer);" +
    "if(!r)return;clearInterval(iv);run();}" +
    "var s=document.createElement('script');s.src=(location.origin||'')+'/assets/ruffle/ruffle.min.js';" +
    "s.onload=boot;s.onerror=boot;document.head.appendChild(s);" +
    "var iv=setInterval(boot,200);" +
    "})();";
  return (
    '<!doctype html><html><head><meta charset="utf-8">' +
    '<style>html,body{margin:0;height:100%;background:#000;overflow:hidden}' +
    'ruffle-player{width:100vw;height:100vh;display:block}</style>' +
    '<script>window.RufflePlayer={autoplay:"on",unmuteOverlay:"hidden"};</script>' +
    "</head><body><script>(function(){" +
    runFn + loader +
    "})();</script></body></html>"
  );
}

